import yaml
from pathlib import Path

# Path to features configuration
FEATURES_PATH = Path(__file__).parent.parent / "config" / "features.yaml"

def load_enabled_flags():
    if not FEATURES_PATH.exists():
        print(f"Warning: {FEATURES_PATH} not found. Using default empty set.")
        return frozenset()

    try:
        with open(FEATURES_PATH, 'r') as f:
            data = yaml.safe_load(f)
            if isinstance(data, list):
                return frozenset(data)
            elif isinstance(data, dict) and 'enabled' in data:
                return frozenset(data['enabled'])
            return frozenset()
    except Exception as e:
        print(f"Error loading features from {FEATURES_PATH}: {e}")
        return frozenset()

ENABLED = load_enabled_flags()


def is_enabled(name):
    return name in ENABLED
